rows=json.loads((EP/'story/sentences.json').read_text())['rows']; beats=json.loads((EP/'storyboard/BEATS-v1.json').read_text())
shots=[]
for row,states,beat in zip(rows,D,beats):
 parts=re.findall(r'.+?[。！？](?:[”’])?|.+$',row['text'])
 # split near character midpoint without rewriting a single character
 lens=[len(re.sub(r'[^\w\u4e00-\u9fff]','',x)) for x in parts]; total=sum(lens)
 k=min(range(1,len(parts)),key=lambda k:abs(sum(lens[:k])/total-.5)) if len(parts)>1 else 1
 cues=[''.join(parts[:k]),''.join(parts[k:])]
 if not cues[1]:cues=[row['text'],'']
 start=round(row['start']*24); end=round(row['end']*24)
 mid=start+round((end-start)*sum(lens[:k])/max(total,1)); bounds=[start,mid,end]
 for j,((scene,cast,visual),cue) in enumerate(zip(states,cues)):
  sid=row['shot']+chr(65+j)
  ids=[x for x in ['protagonist','mother','chen'] if x in cast]
  if cast=='hand':ids=['protagonist']
  if cast=='young' or 'young' in cast:ids.append('young-protagonist')
  shots.append(dict(id=sid,beat_id=row['shot'],line='悬疑',step='single',scene_id=scene,cast=cast,character_ids=ids,character_closeup=scene in ['desk','room-side'],hands_visible=cast=='hand',evidence_id=beat['evidence_id'],subject_class='person' if cast!='none' else 'environment',push_ratio=.1 if cast!='none' else 0,needs_2048=True,single_reason='人物定装/关键动作近景' if cast!='none' else '母题定装或证据关键构图',fact=visual,visual=visual,cue=cue,start_frame=bounds[j],end_frame=bounds[j+1],frames=bounds[j+1]-bounds[j],duration_s=(bounds[j+1]-bounds[j])/24,motion='affine_push' if j==0 and scene not in ['photo-old','photo-gone','photo-child','desk-top'] else 'static',foley_requirement='document-only-no-audio'))
assert ''.join(s['cue'] for s in shots)==''.join(r['text'] for r in rows)
out={'title':'如果你还记得这个地方','estimated_api_calls':'80 formal images + cached empty scene plates (~17) + 3 anchors + 2 intros; retries separately recorded','fps':24,'duration_s':shots[-1]['end_frame']/24,'frames':shots[-1]['end_frame'],'scenes':SCENES,'shots':shots}
